if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:27449e1bed6d4f91099fb4e4' and md5(to_jsonb(t)::text)='92afff7f19e282323ee0b8448060a895')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:27449e1bed6d4f91099fb4e4';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{rules,definition}',$native_e473a6c5ba678da9${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:27449e1bed6d4f91099fb4e4","revision":2,"language":"es","name":"Set de tres dragones","aliases":[],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:ddc8ed6af23c6a9e50409d39e65d061a9c60e994be0b23822f6d671da9db2bc4","kind":"legacy","title":"Set de tres dragones","language":"es","rulesEdition":null,"locator":"official:equipment:es:27449e1bed6d4f91099fb4e4","verified":false},{"id":"original:e4a88ebe8e557a45afba2c20ca233829c7021f2af5501046c295731f69e9dc01","kind":"legacy","title":"Set de tres dragones","language":"es","rulesEdition":null,"locator":"official:equipment:es:27449e1bed6d4f91099fb4e4","verified":false},{"id":"original:19ab0422099874430df4db566754e6d4b43c80c5deff19d3f02814bc070131d8","kind":"legacy","title":"Three-Dragon Ante Set","language":"en","rulesEdition":null,"locator":"official:equipment:eng:be3306e81679e6ee46cec7ff","verified":false},{"id":"original:584f0d4527a4bc3e000de832c6421697b41d3f3c0a3eb6da861d55ae192aded0","kind":"legacy","title":"Three-Dragon Ante Set","language":"en","rulesEdition":null,"locator":"official:equipment:eng:be3306e81679e6ee46cec7ff","verified":false},{"id":"phb-supplied-equipment","kind":"book","title":"Manual del Jugador 2014 · documento español aportado por el GM","language":"es","rulesEdition":"2014","locator":"C:/Users/joaqu/Downloads/D&D - Manual del Jugador 5E (1).pdf · páginas PDF 128, 129","verified":true},{"id":"srd-5.1-es-tools-context","kind":"srd","title":"SRD 5.1 · herramientas, instrumentos y juegos · español oficial","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · páginas PDF 72–73 · CC BY 4.0","verified":true}],"category":"tool","subtypes":["gaming-set"],"magical":false,"rarity":"none","consumable":false,"properties":[],"weight":null,"economy":{"basePrice":{"quantity":1,"unit":"gp"},"campaignPrice":null,"explanation":"Precio de la tabla Herramientas del manual aportado."},"description":[{"id":"game-row","section":"description","provenance":"reviewed-translation","sourceIds":["phb-supplied-equipment"],"type":"table","columns":["Objeto","Precio","Peso"],"rows":[["Set de tres dragones","1 po","—"]]},{"id":"source-text","section":"rules","provenance":"reviewed-translation","sourceIds":["phb-supplied-equipment"],"type":"paragraph","text":"Set de Juego. Este objeto engloba un amplio rango de piezas de juego incluyendo dados y barajas de cartas (para juegos tales como Tres dragones). Unos pocos ejemplos comunes aparecen en la tabla Herramientas pero existen otro tipo de sets de juego. Si eres competente con un set de juego puedes añadir tu bonificador de competencia a las pruebas de característica que realices para jugar a un juego con este set. Cada tipo de set de juego requiere una competencia por separado."},{"id":"tools-context-general","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-tools-context"],"type":"paragraph","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza."},{"id":"tools-context-gaming","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-tools-context"],"type":"paragraph","text":"Juegos. Esta categoría de objetos incluye varios tipos de juegos de azar, normalmente basados en dados o cartas (como la Apuesta de los Tres Dragones). En la tabla “Herramientas” aparecen algunos ejemplos comunes, pero existen otros. Si eres competente con un juego, puedes sumar tu bonificador por competencia a las pruebas de característica que hagas para jugar con él. Cada tipo de juego requiere su propia competencia independiente."}],"requirements":{"attunement":false,"bearer":[],"presence":"possessed","explanation":"Equipo mundano; no requiere sintonización."},"weapon":null,"armor":null,"resources":[],"capabilities":[{"id":"mundane-assisted-use","name":"Jugar con competencia","activation":"other","trigger":"","requirements":{"attunement":false,"bearer":[],"presence":"possessed","explanation":"Equipo mundano; no requiere sintonización."},"target":"Portador","range":"","duration":"Según su uso.","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"tool-check","kind":"tool-check","toolKey":"three-dragon-ante-set","condition":""}],"execution":{"mode":"automatic","handler":"equipment-tool-check","explanation":"Prueba de herramienta con característica elegida, competencia, pericia y Talento Seguro cuando corresponden.","pendingAutomation":[]},"textBlockIds":["source-text"]}],"recoverySourceIds":["ddc8ed6af23c6a9e50409d39e65d061a9c60e994be0b23822f6d671da9db2bc4","e4a88ebe8e557a45afba2c20ca233829c7021f2af5501046c295731f69e9dc01","19ab0422099874430df4db