s bonos fijos no se duplican en los críticos.","pendingAutomation":[]},"textBlockIds":["family-rule"]}],"recoverySourceIds":["e0f8705d0110a6692630c9f06747bbc61075edff2050c44793de283fae85314f","0d370e3c353b4e17c9f09a2388dfdb6bbc58283824f5e93d47c970ae3c5be212","6be91ed15db75dd5d4347325bf1f6b77673a1d6dfad2f5467534d6b3c8ac1c47","1c20adadb86f6bdeb1475de83f7e72ef0194d9460e86a7519f8d7084493eca80"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":true,"unresolved":["Cerrar la cobertura de todos los campos originales antes de migrar o retirar versiones."]}}$native_df9ba714949f0d55$::jsonb,true),'{features}',$native_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$native_4543b46f281f3b43$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:412fed1c4f5ada1768df781f';
