itle":"SRD 5.1 · original inglés","language":"en","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1.pdf · páginas PDF 66 · CC BY 4.0","verified":true},{"id":"srd-5.1-attribution","kind":"srd","title":"Atribución y licencia del SRD 5.1","language":"es","rulesEdition":"2014","locator":"Esta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es.","verified":true},{"id":"dmg-2014-vicious","kind":"book","title":"Dungeon Master’s Guide (2014) · Vicious Weapon","language":"en","rulesEdition":"2014","locator":"https://www.dndbeyond.com/magic-items/5399-vicious-weapon · Legacy","verified":true}],"category":"weapon","subtypes":[],"magical":true,"rarity":"rare","consumable":false,"properties":["thrown","versatile","magic"],"weight":{"value":4,"unit":"lb"},"economy":{"basePrice":null,"campaignPrice":null,"explanation":"La tabla describe el objeto mundano base; no fija el precio de la variante mágica. Precios personales y comerciales conservados en los originales."},"description":[{"id":"official-base-table","section":"description","provenance":"reviewed-translation","sourceIds":["srd-5.1-en-equipment"],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)","Daño versátil"],"rows":[["Tridente","5 po","4 lb","1d6 perforante","+0","Arrojadiza, Versátil","20/60","1d8"]]},{"id":"property-thrown","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”."},{"id":"property-versatile","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Versátil. Estas armas pueden utilizarse con una o con dos manos. Tras esta propiedad aparece entre paréntesis un valor de daño, que será el que uses cuando emplees esta arma a dos manos para hacer un ataque cuerpo a cuerpo."},{"id":"family-rule","section":"rules","provenance":"reviewed-translation","sourceIds":["dmg-2014-vicious"],"type":"paragraph","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma."}],"requirements":{"attunement":false,"bearer":[],"presence":"held","explanation":"No requiere sintonización. La competencia determina los beneficios y restricciones de uso, no es una condición para poseer el objeto."},"weapon":{"category":"martial","meleeReachFeet":5,"thrown":true,"rangeFeet":{"normal":20,"long":60},"attackBonus":0,"damageBonus":0,"baseDamage":[{"id":"base-damage","condition":"","kind":"damage","expression":"1d6","damageType":"piercing","timing":"base"},{"id":"versatile-damage","condition":"Empleada a dos manos en un ataque cuerpo a cuerpo.","kind":"damage","expression":"1d8","damageType":"piercing","timing":"versatile"}]},"armor":null,"resources":[],"capabilities":[{"id":"vicious-natural-20","name":"Daño adicional con un 20 natural","activation":"trigger","trigger":"Un 20 natural en la tirada de ataque con esta arma.","requirements":{"attunement":false,"bearer":[],"presence":"held","explanation":"No requiere sintonización. La competencia determina los beneficios y res